'use client';

import { useState } from 'react';
import { useAuth } from '@/contexts/AuthContext';
import { UserRole } from '@/lib/permissions';
import { Shield, ChevronDown } from 'lucide-react';

const ROLE_OPTIONS = [
  { value: UserRole.SUPER_ADMIN, label: '超级管理员', color: 'text-purple-600' },
  { value: UserRole.ADMIN, label: '管理员', color: 'text-blue-600' },
  { value: UserRole.EDITOR, label: '编辑', color: 'text-green-600' },
  { value: UserRole.REVIEWER, label: '审核员', color: 'text-orange-600' },
  { value: UserRole.VIEWER, label: '查看者', color: 'text-gray-600' },
];

export default function RoleSwitcher() {
  const { user, updateUserRole } = useAuth();
  const [isOpen, setIsOpen] = useState(false);

  if (!user) return null;

  const currentRole = ROLE_OPTIONS.find((r) => r.value === user.role);

  return (
    <div className="relative">
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="flex items-center gap-2 px-3 py-2 bg-white border border-gray-200 rounded-lg hover:bg-gray-50 transition-colors"
      >
        <Shield className="w-4 h-4" />
        <span className="text-sm font-medium">{currentRole?.label}</span>
        <ChevronDown className="w-4 h-4" />
      </button>

      {isOpen && (
        <>
          <div
            className="fixed inset-0 z-10"
            onClick={() => setIsOpen(false)}
          />
          <div className="absolute top-full mt-2 right-0 w-48 bg-white border border-gray-200 rounded-lg shadow-lg z-20 py-1">
            {ROLE_OPTIONS.map((role) => (
              <button
                key={role.value}
                onClick={() => {
                  updateUserRole(role.value);
                  setIsOpen(false);
                }}
                className={`w-full text-left px-4 py-2 text-sm hover:bg-gray-50 transition-colors ${
                  user.role === role.value ? 'bg-blue-50 font-medium' : ''
                } ${role.color}`}
              >
                {role.label}
              </button>
            ))}
          </div>
        </>
      )}
    </div>
  );
}
